const rows = document.querySelectorAll('tr.athing');
const out = [];
for (const r of Array.from(rows).slice(0, args.limit ?? 30)) {
  const titleA = r.querySelector('.titleline > a');
  const rank = r.querySelector('.rank')?.textContent?.replace('.', '').trim();
  const subtext = r.nextElementSibling?.querySelector('.subtext');
  const score = subtext?.querySelector('.score')?.textContent;
  const author = subtext?.querySelector('.hnuser')?.textContent;
  const commentsA = subtext?.querySelector('a:last-child');
  out.push({
    rank: rank ? Number(rank) : null,
    title: titleA?.textContent?.trim(),
    url: titleA?.getAttribute('href'),
    score,
    author,
    comments_text: commentsA?.textContent?.trim(),
    item_id: r.id,
  });
}
return { stories: out };
